import org.apache.commons.math.exception.util.LocalizedFormats;
import org.apache.commons.math.stat.descriptive.AbstractStorelessUnivariateStatistic;
import org.apache.commons.math.stat.descriptive.WeightedEvaluation;
import org.apache.commons.math.util.MathUtils;
import org.junit.*;
import org.junit.Assert;
import org.junit.Test;
import static org.junit.Assert.*;

public class Variance_evaluate_TriageGen0Test {

    private static final double EPSILON = 1e-9;







    @Test
    public void testEvaluate_LengthGreaterThanOne_Unbiased() {
        Variance variance = new Variance(true); // isBiasCorrected = true
        double[] values = {1.0, 2.0, 3.0};
        double[] weights = {1.0, 1.0, 1.0};
        double mean = 2.0;
        // sumWts = 3.0
        // devs: (1-2)=-1, (2-2)=0, (3-2)=1
        // accum = 1*(1^2) + 1*(0^2) + 1*(1^2) = 2.0
        // accum2 = 1*(-1) + 1*(0) + 1*(1) = 0.0
        // var = (2.0 - (0/3)) / (3 - 1) = 2.0 / 2.0 = 1.0
        double result = variance.evaluate(values, weights, mean, 0, 3);
        Assert.assertEquals(1.0, result, EPSILON);
    }






}

