package org.apache.commons.math.stat.descriptive.moment;

import java.io.*;
import java.io.Serializable;
import java.math.*;
import java.util.*;
import org.apache.commons.math.exception.NullArgumentException;
import org.apache.commons.math.exception.util.LocalizedFormats;
import org.apache.commons.math.stat.descriptive.AbstractStorelessUnivariateStatistic;
import org.apache.commons.math.stat.descriptive.WeightedEvaluation;
import org.apache.commons.math.util.MathUtils;
import org.junit.*;
import org.junit.Assert;
import org.junit.Test;
import static org.junit.Assert.*;

public class Variance_evaluate_TriageGen0Test {

    private static final double EPSILON = 1e-9;











    @Test
    public void testEvaluate_WeightedUneven() {
        Variance variance = new Variance(false);
        double[] values = {1.0, 3.0};
        double[] weights = {2.0, 1.0}; // sumWts = 3.0
        double mean = 1.6666666666666667; // (1*2 + 3*1)/3

        // dev1 = 1 - 1.666... = -0.666...
        // dev2 = 3 - 1.666... = 1.333...
        // accum = 2 * (-2/3)^2 + 1 * (4/3)^2 = 2*(4/9) + 16/9 = 8/9 + 16/9 = 24/9 = 2.666...
        // accum2 = 2 * (-2/3) + 1 * (4/3) = -4/3 + 4/3 = 0
        // var = 2.666... / 3.0 = 0.888...

        double result = variance.evaluate(values, weights, mean, 0, 2);
        Assert.assertEquals(24.0 / 27.0, result, EPSILON);
    }


}

package org.apache.commons.math.stat.descriptive.moment;

import java.io.*;
