import org.apache.commons.math.exception.util.LocalizedFormats;
import org.apache.commons.math.stat.descriptive.AbstractStorelessUnivariateStatistic;
import org.apache.commons.math.stat.descriptive.WeightedEvaluation;
import org.apache.commons.math.util.MathUtils;
import org.junit.*;
import org.junit.Assert;
import org.junit.Test;
import static org.junit.Assert.*;

public class Variance_evaluate_TriageGen0Test {

    private static final double EPSILON = 1e-9;













    @Test
    public void testEvaluate_NonZeroAccum2() {
        // Test case where accum2 is not zero to ensure the formula (accum - (accum2 * accum2 / sumWts)) works
        Variance variance = new Variance(false);
        double[] values = {1.0, 2.0};
        double[] weights = {1.0, 1.0};
        double mean = 1.0; // Artificial mean to force accum2 != 0
        // dev1 = 1-1=0, dev2 = 2-1=1
        // accum = 1*(0^2) + 1*(1^2) = 1.0
        // accum2 = 1*(0) + 1*(1) = 1.0
        // sumWts = 2.0
        // var = (1.0 - (1.0 * 1.0 / 2.0)) / 2.0 = (0.5) / 2.0 = 0.25
        double result = variance.evaluate(values, weights, mean, 0, 2);
        Assert.assertEquals(0.25, result, EPSILON);
    }
}
